CREATE TABLE IF NOT EXISTS draws (id INTEGER PRIMARY KEY AUTOINCREMENT,draw_date TEXT NOT NULL UNIQUE,weekday INTEGER NOT NULL,day INTEGER NOT NULL,month INTEGER NOT NULL,year_be INTEGER NOT NULL,lunar_side TEXT NOT NULL CHECK(lunar_side IN ('ข้างขึ้น','ข้างแรม')),first_prize TEXT NOT NULL,last3_1 TEXT,last3_2 TEXT,last2 TEXT NOT NULL,source TEXT DEFAULT 'GLO',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_draws_date ON draws(draw_date);CREATE INDEX IF NOT EXISTS idx_draws_filters ON draws(weekday,day,month,year_be,lunar_side);